using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using System.Web.Script.Serialization;
using System.Windows.Automation;

class BootstrapUiSmoke {
    static void Require(bool value,string message){if(!value)throw new Exception(message);}
    static AutomationElement WaitWindow(int processId,string title,int seconds=15){var deadline=DateTime.UtcNow.AddSeconds(seconds);while(DateTime.UtcNow<deadline){var condition=new AndCondition(new PropertyCondition(AutomationElement.ProcessIdProperty,processId),new PropertyCondition(AutomationElement.NameProperty,title));var found=AutomationElement.RootElement.FindFirst(TreeScope.Children,condition);if(found!=null)return found;Thread.Sleep(100);}var windows=AutomationElement.RootElement.FindAll(TreeScope.Children,new PropertyCondition(AutomationElement.ProcessIdProperty,processId)).Cast<AutomationElement>().Select(item=>"'"+item.Current.Name+"'");throw new Exception("Window did not open: "+title+" (PID "+processId+"). Visible: "+String.Join(", ",windows));}
    static AutomationElement Find(AutomationElement root,AutomationProperty property,object value){var found=root.FindFirst(TreeScope.Descendants,new PropertyCondition(property,value));if(found==null)throw new Exception("UI element was not found: "+value);return found;}
    static void Invoke(AutomationElement element){((InvokePattern)element.GetCurrentPattern(InvokePattern.Pattern)).Invoke();}
    static Process Launch(string executable,string arguments){var process=Process.Start(new ProcessStartInfo(executable,arguments){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(executable)});Require(process!=null,"Packaged process was not created");return process;}
    static void WaitFor(Func<bool> condition,string message,int seconds=15){var deadline=DateTime.UtcNow.AddSeconds(seconds);while(DateTime.UtcNow<deadline){if(condition())return;Thread.Sleep(100);}throw new Exception(message);}
    static string ReadText(string path){try{return File.Exists(path)?File.ReadAllText(path):"";}catch(IOException){return "";}}
    static string Quote(string value){return "\""+value.Replace("\"","\\\"")+"\"";}
    static void ContinueOfflineIfPrompted(int processId){AutomationElement dialog=null;var deadline=DateTime.UtcNow.AddSeconds(5);while(DateTime.UtcNow<deadline){var condition=new AndCondition(new PropertyCondition(AutomationElement.ProcessIdProperty,processId),new PropertyCondition(AutomationElement.NameProperty,"Connect this profile"));dialog=AutomationElement.RootElement.FindFirst(TreeScope.Descendants,condition);if(dialog!=null)break;Thread.Sleep(100);}if(dialog!=null)Invoke(Find(dialog,AutomationElement.NameProperty,"Continue Offline"));}
    static void SelectCard(AutomationElement chooser,string profileName){AutomationElement text=null;WaitFor(()=>{text=chooser.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.NameProperty,profileName));return text!=null;},"Profile card was not found: "+profileName);var item=text;while(item!=null&&item.Current.ControlType!=ControlType.ListItem)item=TreeWalker.ControlViewWalker.GetParent(item);if(item==null)throw new Exception("Profile card was not selectable: "+profileName);((SelectionItemPattern)item.GetCurrentPattern(SelectionItemPattern.Pattern)).Select();}
    static string WaitReplacementPid(string logPath,int priorPid){int replacement=0;WaitFor(()=>{foreach(string line in ReadText(logPath).Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Reverse()){var match=Regex.Match(line,@"restart-launched replacement-pid=(\d+)");if(match.Success&&Int32.TryParse(match.Groups[1].Value,out replacement)&&replacement!=priorPid)return true;}return false;},"Restart did not record a replacement process",30);return replacement.ToString();}
    static Process Switch(Process current,string logPath,string targetName,string targetId){
        var main=WaitWindow(current.Id,"PeerChat");ContinueOfflineIfPrompted(current.Id);var profileButton=Find(main,AutomationElement.AutomationIdProperty,"Profile");new Thread(()=>{try{Invoke(profileButton);}catch{}}){IsBackground=true}.Start();AutomationElement confirmation=null;var deadline=DateTime.UtcNow.AddSeconds(15);while(DateTime.UtcNow<deadline){var condition=new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Window),new PropertyCondition(AutomationElement.NameProperty,"Switch local profile?"));confirmation=AutomationElement.RootElement.FindFirst(TreeScope.Descendants,condition);if(confirmation!=null)break;Thread.Sleep(100);}Require(confirmation!=null,"Profile switch confirmation did not open");var switchButton=Find(confirmation,AutomationElement.NameProperty,"Switch Profile");new Thread(()=>{try{Invoke(switchButton);}catch{}}){IsBackground=true}.Start();int replacement=Int32.Parse(WaitReplacementPid(logPath,current.Id));Require(current.WaitForExit(10000),"Old profile process did not exit after replacement launch");var chooser=WaitWindow(replacement,"Choose local profile");SelectCard(chooser,targetName);Invoke(Find(chooser,AutomationElement.NameProperty,"Open Profile"));WaitWindow(replacement,"PeerChat");ContinueOfflineIfPrompted(replacement);WaitFor(()=>ReadText(logPath).Contains("pid="+replacement+" native-ready profile="+targetId),"Replacement did not open the selected profile");return Process.GetProcessById(replacement);
    }
    static int Main(string[] args){try{
        int listenerPort=args.Length>2?Int32.Parse(args[2]):29642;
        string executable=Path.GetFullPath(args[0]),root=Path.GetFullPath(args[1]),capture=Path.Combine(root,"first-main.png"),log=Path.Combine(root,"startup.log");Directory.CreateDirectory(root);
        var first=Launch(executable,"--install-root "+Quote(root)+" --port "+listenerPort+" --capture "+Quote(capture));var chooser=WaitWindow(first.Id,"Choose local profile");var hiddenEditor=chooser.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Edit));Require(hiddenEditor==null||hiddenEditor.Current.IsOffscreen,"New-profile editor was visible before New Profile was clicked");Invoke(Find(chooser,AutomationElement.NameProperty,"Open Profile"));WaitFor(()=>File.Exists(capture)&&ReadText(log).Contains("main-run-exit"),"Existing profile selection did not open and close the packaged main window",30);Require(first.WaitForExit(30000)&&first.ExitCode==0,"Existing-profile packaged process did not terminate cleanly");string diagnostics=ReadText(log);Require(diagnostics.Contains("chooser-open")&&diagnostics.Contains("profile-selected")&&diagnostics.Contains("main-run-enter")&&diagnostics.Contains("native-ready"),"Startup diagnostics did not reach the native profile");
        string secondCapture=Path.Combine(root,"new-main.png");var second=Launch(executable,"--install-root "+Quote(root)+" --port "+listenerPort+" --capture "+Quote(secondCapture));chooser=WaitWindow(second.Id,"Choose local profile");Invoke(Find(chooser,AutomationElement.NameProperty,"＋ New Profile"));var edit=Find(chooser,AutomationElement.ControlTypeProperty,ControlType.Edit);((ValuePattern)edit.GetCurrentPattern(ValuePattern.Pattern)).SetValue("Profile B");Invoke(Find(chooser,AutomationElement.NameProperty,"Create Profile"));SelectCard(chooser,"Profile B");Invoke(Find(chooser,AutomationElement.NameProperty,"Open Profile"));WaitFor(()=>File.Exists(secondCapture)&&Regex.Matches(ReadText(log),"main-run-exit").Count>=2,"New profile selection did not open and close the packaged main window",30);Require(second.WaitForExit(30000)&&second.ExitCode==0,"New-profile packaged process did not terminate cleanly");
        var catalog=new JavaScriptSerializer().Deserialize<ProfileCatalog>(File.ReadAllText(Path.Combine(root,"profiles.json")));Require(catalog.Profiles.Length==2,"Add Profile did not persist two profiles");var a=catalog.Profiles.First(profile=>profile.Name!="Profile B");var b=catalog.Profiles.First(profile=>profile.Name=="Profile B");
        var active=Launch(executable,"--install-root "+Quote(root)+" --profile-id "+a.Id+" --port "+listenerPort);WaitWindow(active.Id,"PeerChat");ContinueOfflineIfPrompted(active.Id);WaitFor(()=>ReadText(log).Contains("pid="+active.Id+" native-ready profile="+a.Id),"Profile A did not reach native Ready");active=Switch(active,log,b.Name,b.Id);active=Switch(active,log,a.Name,a.Id);var finalWindow=WaitWindow(active.Id,"PeerChat");ContinueOfflineIfPrompted(active.Id);WaitFor(()=>ReadText(log).Contains("pid="+active.Id+" firewall-rule-reused"),"Final profile did not reuse the installation firewall rule");((WindowPattern)finalWindow.GetCurrentPattern(WindowPattern.Pattern)).Close();Require(active.WaitForExit(10000),"Final profile process did not close cleanly");
        diagnostics=ReadText(log);Require(Regex.Matches(diagnostics,"restart-launched replacement-pid=").Count==2,"Switching created an unexpected number of replacement processes");int switchStart=diagnostics.IndexOf("switch-requested",StringComparison.Ordinal);Require(switchStart>=0,"Switch diagnostics were not recorded");string switchDiagnostics=diagnostics.Substring(switchStart);Require(Regex.Matches(switchDiagnostics,"firewall-rule-updated").Count<=1,"Profile switching repeatedly modified the installation firewall rule");Require(Regex.Matches(switchDiagnostics,"firewall-rule-reused").Count>=1,"A-B-A switching did not reuse the installation firewall rule after provisioning the candidate executable path");
        var concurrentA=Launch(executable,"--install-root "+Quote(root)+" --profile-id "+a.Id);var windowA=WaitWindow(concurrentA.Id,"PeerChat");ContinueOfflineIfPrompted(concurrentA.Id);var concurrentB=Launch(executable,"--install-root "+Quote(root)+" --profile-id "+b.Id);var windowB=WaitWindow(concurrentB.Id,"PeerChat");ContinueOfflineIfPrompted(concurrentB.Id);WaitFor(()=>{var value=ReadText(log);return value.Contains("pid="+concurrentA.Id+" native-ready profile="+a.Id)&&value.Contains("pid="+concurrentB.Id+" native-ready profile="+b.Id);},"Different profiles sharing one saved port did not both reach native Ready");Require(!concurrentA.HasExited&&!concurrentB.HasExited,"Different local profiles could not run concurrently");var duplicateA=Launch(executable,"--install-root "+Quote(root)+" --profile-id "+a.Id);var alreadyOpen=WaitWindow(duplicateA.Id,"PeerChat profile already open");Invoke(Find(alreadyOpen,AutomationElement.NameProperty,"OK"));Require(duplicateA.WaitForExit(10000)&&duplicateA.ExitCode==2,"A duplicate profile did not fail cleanly");Require(!concurrentA.HasExited&&!concurrentB.HasExited,"Duplicate-profile rejection disturbed a valid profile process");((WindowPattern)windowA.GetCurrentPattern(WindowPattern.Pattern)).Close();((WindowPattern)windowB.GetCurrentPattern(WindowPattern.Pattern)).Close();Require(concurrentA.WaitForExit(10000)&&concurrentB.WaitForExit(10000),"Concurrent profile processes did not close cleanly");
        diagnostics=ReadText(log);Require(diagnostics.Contains("profile-already-open"),"Duplicate-profile rejection was not diagnosed");Console.WriteLine("PASS: packaged chooser, concurrent distinct profiles, clean duplicate-profile rejection, A-B-A switching, and installation firewall reuse.");return 0;
    }catch(Exception error){Console.Error.WriteLine("FAIL: "+error);return 1;}}
    public class ProfileCatalog {public string SelectedProfileId;public Profile[] Profiles;}
    public class Profile {public string Id;public string Name;}
}
